{
  "name": "OPX量子控制器",
  "name_en": "OPX quantum controller",
  "manufacturer": "Quantum Machines",
  "description": "OPX是Quantum Machines推出的量子控制电子设备，用于在量子实验中生成、同步和执行精确的脉冲序列，触发测量并采集读出结果。它常用于超导量子比特等平台的实验编排、读出控制和自动化测量。",
  "description_en": "The OPX is a quantum control instrument from Quantum Machines used to generate, synchronize, and execute precise pulse sequences, trigger measurements, and acquire readout results in quantum experiments. It is commonly used for experiment orchestration, readout control, and automated measurements on platforms such as superconducting qubits.",
  "tag_hints": [
    "quantum control",
    "OPX",
    "QUA programming",
    "pulse sequencing",
    "qubit readout",
    "superconducting qubits",
    "experiment orchestration"
  ],
  "actions": [
    {
      "action_name": "auto-reset_measurements",
      "description": "重置已添加到OPX程序中的测量项目。",
      "description_en": "Reset the measurements added to the OPX program."
    },
    {
      "action_name": "auto-connect_opx",
      "description": "连接到指定IP地址的OPX量子控制器。",
      "description_en": "Connect to the OPX quantum controller at the specified IP address."
    },
    {
      "action_name": "auto-reconnect_opx",
      "description": "重新连接到指定IP地址的OPX量子控制器。",
      "description_en": "Reconnect to the OPX quantum controller at the specified IP address."
    },
    {
      "action_name": "auto-add_measurement",
      "description": "向OPX控制程序中添加一个测量步骤。",
      "description_en": "Add a measurement step to the OPX control program."
    },
    {
      "action_name": "auto-run",
      "description": "在OPX上执行一个QUA程序。",
      "description_en": "Run a QUA program on the OPX."
    },
    {
      "action_name": "auto-print_qua_program_to_file",
      "description": "将QUA程序导出到文件。",
      "description_en": "Export a QUA program to a file."
    },
    {
      "action_name": "auto-run_local_simulation",
      "description": "在本地模拟OPX程序的执行。",
      "description_en": "Run a local simulation of an OPX program."
    },
    {
      "action_name": "auto-ask_raw",
      "description": "向设备发送原始命令并读取回复。",
      "description_en": "Send a raw command to the device and read the reply."
    },
    {
      "action_name": "auto-write_raw",
      "description": "向设备发送原始写入命令。",
      "description_en": "Send a raw write command to the device."
    },
    {
      "action_name": "auto-create_measurement_from_experiment",
      "description": "根据实验定义创建一个可在OPX流程中使用的测量项目。",
      "description_en": "Create a measurement entry from an experiment definition for use in the OPX workflow."
    },
    {
      "action_name": "auto-check_db_engine_and_bucket_connected",
      "description": "检查实验数据库和存储桶连接状态。",
      "description_en": "Check the connection status of the experiment database and storage bucket."
    },
    {
      "action_name": "auto-measurements",
      "description": "获取OPX程序中定义的测量项目。",
      "description_en": "Get the measurements defined in the OPX program."
    },
    {
      "action_name": "auto-get_idn",
      "description": "获取设备标识信息。",
      "description_en": "Get the device identification information."
    },
    {
      "action_name": "auto-get_run_from_id",
      "description": "获取指定运行ID对应的运行记录。",
      "description_en": "Get the run record for the specified run ID."
    },
    {
      "action_name": "auto-get_data_from_id",
      "description": "获取指定运行ID对应的测量数据。",
      "description_en": "Get the measurement data for the specified run ID."
    }
  ]
}

